const WINPASSAGE_ICON_DATA_URI = 'data:image/png;base64,';

export function winPassageMarkSvg(className = 'brand-svg'): string {
  return `
    <svg class="${className}" viewBox="0 0 96 96" role="img" aria-label="WinPassage secure bridge and lock mark" xmlns="http://www.w3.org/2000/svg">
      <image href="${WINPASSAGE_ICON_DATA_URI}" x="0" y="0" width="96" height="96" preserveAspectRatio="xMidYMid meet" />
    </svg>`;
}

export function winPassageInlineSvg(className = 'inline-brand-svg'): string {
  return winPassageMarkSvg(className);
}
